class DataInformationBlock(TelegramField):
    EXTENSION_BIT_MASK = 0x80  # 1000 0000
    FUNCTION_MASK = 0x30   # 0011 0000
    DATA_FIELD_MASK = 0x0F  # 0000 1111
    MORE_RECORDS_FOLLOW = 0x1F  # 0001 1111

    def __init__(self, parts=None):
        super(DataInformationBlock, self).__init__(parts)

    @property
    def has_extension_bit(self):
        """Check for extension bit on last byte"""
        try:
            return (self.parts[-1] & self.EXTENSION_BIT_MASK) > 0
        except IndexError:
            return False

    @property
    def has_lvar_bit(self):
        """returns true if this record carries an LVAR length byte"""
        try:
            # DIF data field 1101b is variable length (LVAR). The extension
            # bit on a following DIFE only means another DIFE follows.
            if (self.parts[0] & self.DATA_FIELD_MASK) == 0x0D:
                return True
            return (self.parts[1] & self.EXTENSION_BIT_MASK) > 0
        except IndexError:
            return False

    @property
    def is_eoud(self):
        """Check for end of user data bit VIF byte"""
        try:
            dif = self.parts[0]
            if dif in (0x0F, 0x1F):
                return True
        except IndexError:
            pass

        return False

    @property
    def is_manufacturer_specific(self):
        """Check for manufacturer specific record.

        0x0F starts manufacturer specific data until the end of user data.
        0x1F has the same meaning and additionally signals that more records
        follow in the next telegram.
        """
        try:
            dif = self.parts[0]
            if dif in (0x0F, 0x1F):
                return True
        except IndexError:
            pass

        return False

    @property
    def more_records_follow(self):
        try:
            dif = self.parts[0]
            return dif == self.MORE_RECORDS_FOLLOW
        except IndexError:
            pass

        return False

    @property
    def function_type(self):
        try:
            dif = self.parts[0]
        except IndexError:
            return FunctionType.INSTANTANEOUS_VALUE

        # 0x1F: manufacturer specific AND more records follow (next telegram)
        if dif == self.MORE_RECORDS_FOLLOW:
            return FunctionType.MORE_RECORDS_FOLLOW

        if dif == 0x0F:
            # Manufacturer Specific
            return FunctionType.SPECIAL_FUNCTION

        # 0x2F idle filler; 0x3F-0x6F are reserved and must not be parsed
        # as ordinary data records (they would shift the rest of the frame).
        if dif in (0x2F, 0x3F, 0x4F, 0x5F, 0x6F):
            return FunctionType.SPECIAL_FUNCTION_FILL_BYTE

        return FunctionType((dif & self.FUNCTION_MASK) >> 4)

    @property
    def is_variable_length(self):
        try:
            dif = self.parts[0]
            return (dif & self.DATA_FIELD_MASK) == 0x0D
        except IndexError:
            pass

        return False

    @property
    def length_encoding(self):
        # EN 13757-3 data-field nibble -> (byte length, encoding).
        # 8-digit BCD is 4 bytes (not 5) and variable-length data has no
        # fixed size: the LVAR byte in the payload defines it. Getting
        # either wrong shifts every following record.
        try:
            len_enc = self.parts[0] & self.DATA_FIELD_MASK
        except IndexError:
            return (0, DataEncoding.ENCODING_NULL)

        return {
            0: (0, DataEncoding.ENCODING_NULL),
            1: (1, DataEncoding.ENCODING_INTEGER),  # 1 byte int [8 bit]
            2: (2, DataEncoding.ENCODING_INTEGER),  # 2 byte int [16 bit] or date...
            3: (3, DataEncoding.ENCODING_INTEGER),  # 3 byte int [24 bit]
            4: (4, DataEncoding.ENCODING_INTEGER),  # 4 byte int [32 bit] or date...
            5: (4, DataEncoding.ENCODING_REAL),  # 4 byte float [32 bit]
            6: (6, DataEncoding.ENCODING_INTEGER),  # 6 byte int [48 bit]
            7: (8, DataEncoding.ENCODING_INTEGER),  # 8 byte int [64 bit]
            8: (0, DataEncoding.ENCODING_NULL),  # Nothing...
            9: (1, DataEncoding.ENCODING_BCD),  # 2 digit BCD [8 bit]
            10: (2, DataEncoding.ENCODING_BCD),  # 4 digit BCD [16 bit]
            11: (3, DataEncoding.ENCODING_BCD),  # 6 digit BCD [24 bit]
            12: (4, DataEncoding.ENCODING_BCD),  # 8 digit BCD [32 bit]
            13: (0, DataEncoding.ENCODING_VARIABLE_LENGTH),  # variable length
            14: (6, DataEncoding.ENCODING_BCD),  # 12 digit BCD [48 bit]
            15: (0, DataEncoding.ENCODING_NULL)  # Special Function FIXME
        }[len_enc]

