    def has_lvar_bit(self):
        """True when this DIF selects variable-length data (LVAR).

        LVAR is data-field 0x0D, not the extension bit of a following DIFE.
        """
        try:
            return (self.parts[0] & self.DATA_FIELD_MASK) == 0x0D
        except IndexError:
            return False

    @property
    def is_eoud(self):
        """Check for end of user data (manufacturer specific to end of frame)"""
        try:
            dif = self.parts[0]
            # 0x0F: manufacturer specific until end of user data
            # 0x1F: same, plus more records follow in the next telegram
            if dif in (0x0F, 0x1F):
                return True
        except IndexError:
            pass

        return False

    @property
    def is_manufacturer_specific(self):
        """Opaque manufacturer / unknown payload occupies the rest of the frame"""
        try:
            dif = self.parts[0]
            if dif in (0x0F, 0x1F):
                return True
        except IndexError:
            pass

        return False

