          0x00..0xBF  ASCII, length = LVAR
          0xC0..0xCF  positive BCD, length = LVAR - 0xC0
          0xD0..0xDF  negative BCD, length = LVAR - 0xD0
          0xE0..0xEF  binary integer, length = LVAR - 0xE0
